"use client";
import { useEffect, useRef, useState } from "react";
import { hsvToRgb, rgbToHsv, kelvinToRgb, css, type RGB } from "@/lib/color";
import { project, useDrag } from "./use-drag";
import { haptic } from "./haptics";
import { useDoubleTap } from "./use-double-tap";
import { cn } from "./cn";

/**
 * Colour wheel: angle is hue, distance from the centre is saturation. Previews while dragging, commits on release. It ticks each
 * 30 degrees of hue, clicks at the centre (white) and bumps at the rim. Double-tap to go straight to white.
 */
export function ColorWheel({ rgb, onCommit, label, className }: {
  /** The current colour as `[red, green, blue]`, each 0 to 255. */
  rgb: RGB;
  /** Called with the chosen colour when the finger lifts (not on every move). */
  onCommit: (rgb: RGB) => void;
  /** Names the wheel for screen readers: "Lamp colour". */
  label: string;
  className?: string;
}) {
  const [hs, setHs] = useState<[number, number]>(() => { const [h, s] = rgbToHsv(rgb); return [h, s]; });
  const dragging = useRef(false);
  const key = rgb.join();
  useEffect(() => { if (!dragging.current) { const [h, s] = rgbToHsv(rgb); setHs([h, s]); } }, [key]); // eslint-disable-line react-hooks/exhaustive-deps
  const latest = useRef(hs);
  const pick = (x: number, y: number) => {
    dragging.current = true;
    const dx = x - 0.5, dy = y - 0.5, d = Math.hypot(dx, dy) * 2;
    const h = (Math.atan2(dy, dx) * 180 / Math.PI + 360) % 360, s = Math.min(1, d);
    const [ph, ps] = latest.current;
    if (s <= 0.05 && ps > 0.05) haptic("detent"); // through the centre: white
    else if (s >= 1 && ps < 1) haptic("boundary"); // out to the rim
    else if (Math.round(h / 30) !== Math.round(ph / 30)) haptic("tick"); // every 30 degrees of hue
    latest.current = [h, s];
    setHs([h, s]);
  };
  const drag = useDrag((x, y) => pick(x, y), (x, y) => { pick(x, y); dragging.current = false; onCommit(hsvToRgb(...latest.current)); });
  const white = useDoubleTap(() => { const [h0] = latest.current; haptic("medium"); latest.current = [h0, 0]; setHs([h0, 0]); onCommit(hsvToRgb(h0, 0)); });
  const [h, s] = hs, a = h * Math.PI / 180;
  const cur = css(hsvToRgb(h, s));
  return (
    <div data-slot="color-wheel" className={cn("cwheel", className)} role="slider" aria-label={label} aria-valuemin={0} aria-valuemax={360} aria-valuenow={Math.round(h)} aria-valuetext={`Hue ${Math.round(h)} degrees, ${Math.round(s * 100)}% saturation`} tabIndex={0}
      {...drag} onPointerDown={(e) => { drag.onPointerDown(e); white.onPointerDown(e); }} onPointerUp={(e) => { drag.onPointerUp(e); white.onPointerUp(e); }}
      onKeyDown={(e) => { const dh = e.key === "ArrowRight" ? 10 : e.key === "ArrowLeft" ? -10 : 0; if (dh) { const n = (h + dh + 360) % 360; setHs([n, Math.max(s, 0.5)]); onCommit(hsvToRgb(n, Math.max(s, 0.5))); } }}>
      <i className="cthumb" style={{ left: `${50 + Math.cos(a) * s * 50}%`, top: `${50 + Math.sin(a) * s * 50}%`, background: cur }} />
    </div>
  );
}

/** Warm-to-cool strip for white light. The track shows the real colour at each end of the lamp's range. */
export function WhiteStrip({ kelvin, min, max, onCommit, label, className }: {
  /** The current colour temperature in Kelvin. */
  kelvin: number;
  /** The warmest the lamp can go, in Kelvin (the left end). */
  min: number;
  /** The coolest the lamp can go, in Kelvin (the right end). */
  max: number;
  /** Called with the chosen temperature when the finger lifts. */
  onCommit: (k: number) => void;
  /** Names the strip for screen readers. */
  label: string;
  className?: string;
}) {
  const [k, setK] = useState(kelvin);
  const dragging = useRef(false);
  useEffect(() => { if (!dragging.current) setK(kelvin); }, [kelvin]);
  const at = (x: number) => Math.round((min + x * (max - min)) / 50) * 50;
  const grad = Array.from({ length: 6 }, (_, i) => css(kelvinToRgb(min + (i / 5) * (max - min)))).join(",");
  const drag = useDrag((x) => { dragging.current = true; const n = at(x); if ((n <= min || n >= max) && k > min && k < max) haptic("boundary"); else if (Math.round(n / 500) !== Math.round(k / 500)) haptic("tick"); setK(n); }, (x, _y, _el, v) => { dragging.current = false; const n = at(Math.min(1, Math.max(0, project(x, v.vx)))); setK(n); onCommit(n); });
  const p = ((k - min) / (max - min)) * 100;
  return (
    <div data-slot="white-strip" className={cn("wstrip", className)} role="slider" aria-label={label} aria-valuemin={min} aria-valuemax={max} aria-valuenow={k} aria-valuetext={`${k} Kelvin`} tabIndex={0}
      style={{ background: `linear-gradient(90deg,${grad})` }} {...drag}
      onKeyDown={(e) => { const d = e.key === "ArrowRight" ? 200 : e.key === "ArrowLeft" ? -200 : 0; if (d) { const n = Math.min(max, Math.max(min, k + d)); setK(n); onCommit(n); } }}>
      <i className="wthumb" style={{ left: `${p}%`, background: css(kelvinToRgb(k)) }} />
      <small className="wk">{k}K</small>
    </div>
  );
}

/**
 * A window with a shade you pull: drag down to close, up to open. Previews live, commits on release. It clicks at each quarter,
 * and if you pull past either end it stretches with growing resistance and bumps, then settles back. A flick carries on.
 */
export function CoverShade({ pos, moving, onCommit, label, className }: {
  /** How open the cover is: 0 closed, 100 open. */
  pos: number;
  /** Pulses the handle while the cover is moving. */
  moving: boolean;
  /** Called with the chosen position when the finger lifts. */
  onCommit: (p: number) => void;
  /** Names the control for screen readers. */
  label: string;
  className?: string;
}) {
  const [p, setP] = useState(pos);
  const dragging = useRef(false);
  useEffect(() => { if (!dragging.current) setP(pos); }, [pos]);
  const [rb, setRb] = useState(0); // px the pull has stretched past an end: the further, the harder (rubber-banding)
  const past = useRef(false);
  const at = (y: number) => Math.round(((1 - y) * 100) / 5) * 5;
  const drag = useDrag((_, y, _el, raw) => {
    dragging.current = true;
    const n = at(y), over = raw.y < 0 ? raw.y : raw.y > 1 ? raw.y - 1 : 0;
    setRb(over === 0 ? 0 : Math.sign(over) * (1 - 1 / (Math.abs(over) * 3 + 1)) * 28);
    if (over !== 0 && !past.current) haptic("boundary"); else if (over === 0 && n !== p) haptic(n % 25 === 0 ? "detent" : "tick");
    past.current = over !== 0;
    setP(n);
  }, (_, y, _el, v) => { dragging.current = false; setRb(0); past.current = false; const n = at(Math.min(1, Math.max(0, project(y, v.vy)))); setP(n); onCommit(n); });
  return (
    <div data-slot="cover-shade" className={cn("cshade", className)} role="slider" aria-label={label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={p} tabIndex={0} data-moving={moving || undefined} {...drag}
      onKeyDown={(e) => { const d = e.key === "ArrowUp" ? 10 : e.key === "ArrowDown" ? -10 : 0; if (d) { const n = Math.min(100, Math.max(0, p + d)); setP(n); onCommit(n); } }}>
      <i className="cpane" /><i className="cblind" style={{ height: `max(0px, calc(${100 - p}% + ${rb}px))` }} /><i className="chandle" style={{ top: `${100 - p}%`, translate: `0 ${rb}px` }} />
    </div>
  );
}

.cwheel{position:relative;width:min(240px,64vw);aspect-ratio:1;margin:4px auto;border-radius:50%;touch-action:none;cursor:pointer;-webkit-user-select:none;user-select:none;
  background:radial-gradient(circle,#fff 0%,rgba(255,255,255,0) 70%),conic-gradient(from 90deg,#f00,#ff0,#0f0,#0ff,#00f,#f0f,#f00);box-shadow:var(--shadow),inset 0 0 0 1px var(--line)}
.cthumb{position:absolute;width:32px;height:32px;margin:-16px 0 0 -16px;border-radius:50%;border:3px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.4);pointer-events:none}
.cwheel:active .cthumb{scale:1.15}
.cwheel:focus-visible,.wstrip:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.wstrip{position:relative;height:56px;border-radius:22px;touch-action:none;cursor:pointer;-webkit-user-select:none;user-select:none;box-shadow:inset 0 0 0 1px var(--line)}
.wthumb{position:absolute;top:50%;width:30px;height:30px;margin:-15px 0 0 -15px;border-radius:50%;border:3px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.4);pointer-events:none}
.wk{position:absolute;right:12px;top:-20px;font-variant-numeric:tabular-nums}
.moods{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.moods .btn{padding:8px 0;flex-direction:column;gap:4px;height:auto;font-size:0.75rem}
.moods .sw{width:22px;height:22px;border-radius:50%;box-shadow:inset 0 0 0 1px var(--line)}
.dt{--tint:var(--glow)}
.dt.is-on.tinted{background:color-mix(in srgb,var(--tint) 22%,var(--tile))}
.dt.is-on.tinted>.dfill{background:color-mix(in srgb,var(--tint) 30%,transparent)}
.dt.dragging{transition:none;scale:1.02}
@media (prefers-reduced-motion:reduce){.cwheel:active .cthumb,.dt.dragging{scale:1}}
.cshade{position:relative;width:min(220px,60vw);height:230px;margin:2px auto;border-radius:14px;overflow:hidden;touch-action:none;cursor:ns-resize;-webkit-user-select:none;user-select:none;box-shadow:var(--shadow),inset 0 0 0 3px var(--line);background:linear-gradient(180deg,var(--glow-soft),var(--tile2))}
.cblind{position:absolute;left:0;right:0;top:0;background:repeating-linear-gradient(180deg,var(--tile) 0 9px,var(--tile2) 9px 11px);border-bottom:3px solid var(--ink3);transition:height .35s var(--ease-ios)}
.chandle{position:absolute;left:50%;width:46px;height:8px;margin:-4px 0 0 -23px;border-radius:6px;background:var(--ink);pointer-events:none;transition:top .35s var(--ease-ios),translate .45s var(--spring)}
.cshade:active .cblind,.cshade:active .chandle{transition:none}
.cshade[data-moving] .chandle{animation:cpulse 1s ease-in-out infinite}
@keyframes cpulse{50%{opacity:.35}}
.cshade:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.cbtns{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:8px}
@media (prefers-reduced-motion:reduce){.cblind,.chandle{transition:none}.cshade[data-moving] .chandle{animation:none}}

"use client";
import { useRef, type PointerEvent } from "react";

/** Where the pointer is, as fractions of the element, *not* clamped: below 0 or above 1 means it is past the edge (for rubber-banding). */
export interface DragRaw { x: number; y: number }

/** How fast the pointer was moving when it lifted, as fractions of the element per second (positive is right and down). */
export interface DragVelocity { vx: number; vy: number }

/**
 * Where something flicked from `pos` (0 to 1) with velocity `vel` (fractions per second) comes to rest. A flick carries on after the
 * finger lifts, the way a scroll view does: the distance is the sum of a decelerating glide. `rate` is how quickly it slows
 * (0.998 glides a long way, 0.99 a short one). The result is not clamped.
 */
export const project = (pos: number, vel: number, rate = 0.99) => pos + ((vel / 1000) * rate) / (1 - rate);

const WINDOW_MS = 90; // velocity is read from the last moments of the drag, not its whole length

/**
 * Pointer-capture drag over an element. `move` gets the pointer as 0 to 1 fractions of the element's box (clamped), and as a fourth
 * argument the same position unclamped (so a control can stretch when pulled past its end);
 * `end` fires on release with the last position and the velocity at the moment of release (use it with `project`
 * to let a flick carry on). Props go on the element itself.
 */
export function useDrag(
  move: (x: number, y: number, el: HTMLElement, raw: DragRaw) => void,
  end?: (x: number, y: number, el: HTMLElement, v: DragVelocity) => void,
) {
  const live = useRef(false);
  const last = useRef<[number, number]>([0, 0]);
  const raw = useRef<DragRaw>({ x: 0, y: 0 });
  const trail = useRef<{ t: number; x: number; y: number }[]>([]);
  const at = (e: PointerEvent<HTMLElement>): [number, number] => {
    const r = e.currentTarget.getBoundingClientRect();
    raw.current = { x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height };
    return [Math.min(1, Math.max(0, raw.current.x)), Math.min(1, Math.max(0, raw.current.y))];
  };
  const note = () => {
    const now = performance.now(), [x, y] = last.current;
    trail.current.push({ t: now, x, y });
    while (trail.current.length > 1 && now - trail.current[0].t > WINDOW_MS) trail.current.shift();
  };
  const velocity = (): DragVelocity => {
    const a = trail.current[0], b = trail.current[trail.current.length - 1];
    const dt = a && b ? b.t - a.t : 0;
    return dt > 8 ? { vx: ((b.x - a.x) / dt) * 1000, vy: ((b.y - a.y) / dt) * 1000 } : { vx: 0, vy: 0 };
  };
  return {
    onPointerDown: (e: PointerEvent<HTMLElement>) => { live.current = true; trail.current = []; e.currentTarget.setPointerCapture(e.pointerId); last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerMove: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerUp: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; live.current = false; end?.(...last.current, e.currentTarget, velocity()); },
    onPointerCancel: () => { live.current = false; },
    "data-base-ui-swipe-ignore": true,
  } as const;
}
